#!/usr/bin/env bash
# Builds the Static Web App's content from web/ for one environment: copies the
# pages, styles and scripts, and writes the two generated files.
#
#   .github/scripts/build-web.sh <terraform outputs JSON> <out dir>
#
# - config.js: the account, producer and consumer apps' https:// hosts, whether
#   Stripe is in test mode (the banner), the packs without their Stripe
#   prices, whether prices include VAT, and the contact address.
# - staticwebapp.config.json: the CSP (fetches only to the account app, no
#   inline code, no framing), Referrer-Policy and nosniff, on every response.
set -euo pipefail

outputs=${1:?usage: $0 <terraform outputs JSON> <out dir>}
out=${2:?usage: $0 <terraform outputs JSON> <out dir>}
root=$(cd "$(dirname "$0")/../.." && pwd)

output() { jq -er ".$1.value" <<<"$outputs"; }
# jq -e fails on false, so booleans are checked by type.
bool_output() { jq -c ".$1.value | if type == \"boolean\" then . else error(\"output $1 missing\") end" <<<"$outputs"; }
account="https://$(output accountHostName)"
producer="https://$(output producerHostName)"
consumer="https://$(output consumerHostName)"
test_mode=$(bool_output testMode)
packs=$(jq -ec '.publicPacks.value' <<<"$outputs")
include_vat=$(bool_output pricesIncludeVat)
contact=$(jq -r '.contactEmail.value // ""' <<<"$outputs")

rm -rf "$out"
mkdir -p "$out"
# Only what the site serves: not README.md, config.local.js or a local config.js.
cp "$root"/web/*.html "$root"/web/style.css "$root"/web/app.js "$out"/

jq -nr --arg a "$account" --arg p "$producer" --arg c "$consumer" \
  --argjson test "$test_mode" --argjson packs "$packs" --argjson vat "$include_vat" --arg contact "$contact" '
  "// Generated by .github/scripts/build-web.sh.",
  "window.ACCOUNT_API = \($a | tojson);",
  "window.PRODUCER_API = \($p | tojson);",
  "window.CONSUMER_API = \($c | tojson);",
  "window.TEST_MODE = \($test | tojson);",
  "window.PACKS = \($packs | tojson);",
  "window.PRICES_INCLUDE_VAT = \($vat | tojson);",
  "window.CONTACT_EMAIL = \($contact | tojson);"' >"$out/config.js"

csp="default-src 'self'; connect-src 'self' $account; frame-ancestors 'none'; base-uri 'none'; form-action 'self'"
jq -n --arg csp "$csp" '{
  globalHeaders: {
    "Content-Security-Policy": $csp,
    "Referrer-Policy": "no-referrer",
    "X-Content-Type-Options": "nosniff"
  }
}' >"$out/staticwebapp.config.json"

echo "Built $out for $account:" >&2
ls "$out" >&2
